/**
 * Words the learner said to Siri in the iPhone app ("Add a word to
 * Lexpad"), taken in through the normal add path. The shell only kept what
 * Siri heard (`SaveWordIntent` in the iOS shell); every rule about a word
 * lives here, in `addWord` and on the server.
 *
 * Learners bring their own words: each queued word is exactly what the
 * learner said, and AI only enriches it. Fill with AI runs for those words
 * alone, and only when the learner has already allowed AI on this device;
 * the consent sheet is never raised by a word that arrived while nobody was
 * asking, and the server's allowance decides the rest. When either says no
 * the word stays plain, like any word saved without a meaning, and the
 * notebook's Fill with AI offers it later.
 */
import { canBeCard, normalizeIntroWord } from '@/features/intro/introDraft.js';
import { trackWords } from '@/features/celebrate/state.js';
import { addWord } from '@/db/mutations.js';
import { getActiveNotebook } from '@/db/repo.js';
import { db, type LexpadDb } from '@/db/schema.js';
import type { SiriAdd } from '@/lib/platform/index.js';

/** What became of a batch of words said to Siri. */
export interface AppliedAdds {
  /** The notebook they went into; undefined when there is none yet. */
  notebookId?: string;
  /** Ids of the words added or raised, in the order they were said. */
  wordIds: string[];
  /** Words that will never be added: another account's, or nothing left once cleaned. */
  dropped: number;
  /** Every queued item that was dealt with, to acknowledge to the shell. */
  done: string[];
}

/** Control and direction-override characters, which a headword never keeps. */
// eslint-disable-next-line no-control-regex -- refusing control characters is the point
const REFUSED = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f-\u009f‪-‮⁦-⁩]/gu;

/**
 * The word as it will be saved, or '' when nothing in it can be a card. The
 * shell cleaned it already; this side never trusts a bridge.
 */
export function cleanSaidWord(raw: string): string {
  const word = normalizeIntroWord(raw.replace(/\s+/gu, ' ').replace(REFUSED, ''));
  return canBeCard(word) ? word : '';
}

/**
 * Adds each queued word, oldest first, to the notebook in view, through
 * `addWord`: a word the notebook already has is raised to the top, as a
 * typed one would be. Another account's words are dropped (the phone changed
 * hands). With no notebook yet (an account still in onboarding) nothing is
 * done and nothing acknowledged, so the words wait for the next start.
 */
export async function applySiriAdds(
  adds: readonly SiriAdd[],
  account: string,
  timeZone: string,
  database: LexpadDb = db,
): Promise<AppliedAdds> {
  const out: AppliedAdds = { wordIds: [], dropped: 0, done: [] };
  const ordered = [...adds].sort((a, b) => Date.parse(a.at) - Date.parse(b.at));
  const theirs = ordered.filter((add) => add.account !== account);
  const mine = ordered.filter((add) => add.account === account);
  for (const add of theirs) {
    out.dropped += 1;
    out.done.push(add.id);
  }
  if (mine.length === 0) return out;
  const notebook = await getActiveNotebook(database);
  if (notebook === undefined) return out;
  out.notebookId = notebook.id;
  for (const add of mine) {
    const headword = cleanSaidWord(add.word);
    if (headword === '') {
      out.dropped += 1;
      out.done.push(add.id);
      continue;
    }
    const id = await trackWords(() =>
      addWord(notebook.id, { headword, meaning: '', category: 'general' }, timeZone, database),
    );
    if (!out.wordIds.includes(id)) out.wordIds.push(id);
    out.done.push(add.id);
  }
  return out;
}

/**
 * Fill with AI for the words Siri brought, when AI is already allowed on
 * this device and not resting after a refusal; the same run, lock and
 * remembered jobs as the notebook's own button, limited to these words.
 */
export async function fillSaidWords(
  notebookId: string,
  wordIds: readonly string[],
  unconfirmed: boolean,
): Promise<void> {
  if (wordIds.length === 0) return;
  const [{ aiConsentGiven }, { aiPausedUntil }, { useFill }] = await Promise.all([
    import('@/features/ai/consent.js'),
    import('@/features/ai/quota.js'),
    import('@/features/ai/fill.js'),
  ]);
  if (!aiConsentGiven()) return;
  if ((await aiPausedUntil()) !== undefined) return;
  await useFill.getState().start(notebookId, { ids: new Set(wordIds), unconfirmed });
}
