/**
 * Keeps the home-screen widgets (Android and iPhone) in step with the app, for as long
 * as an account is signed in (started by AuthGate).
 *
 * On start and every return to the foreground it first applies the answers
 * given on the word-card widget (`answers.ts`), then, in the iPhone app,
 * adds the words said to Siri (`adds.ts`), then sends a fresh snapshot
 * (`snapshot.ts`). After that a snapshot follows every change to what the
 * widgets show — an answer, an add, an edit, a delete, a notebook switch,
 * whatever a sync pulled from another device — within SNAPSHOT_DEBOUNCE_MS
 * (Dexie's `storagemutated`, filtered to the tables a snapshot reads), and
 * goes out at once when the app is hidden. Nothing polls: the shell redraws
 * only when this side sends something new, and at local midnight from the
 * snapshot's own `soon` days.
 */
import { Dexie, type ObservabilitySet } from 'dexie';
import { loadToday } from '@/features/today/data.js';
import { localTimeZone } from '@/lib/format.js';
import { platform } from '@/lib/platform/index.js';
import type { HomeWidgets, WidgetSnapshot, WidgetTarget } from '@/lib/platform/index.js';
import { useAuth } from '@/features/auth/session.js';
import { flushPractice, syncSoon, useSync } from '@/sync/store.js';
import { applySiriAdds, fillSaidWords } from './adds.js';
import { applyWidgetAnswers } from './answers.js';
import { loadWidgetSnapshot } from './snapshot.js';
import { holdSurface, withSurface } from '@/lib/surface.js';

/**
 * How long a burst of changes (a session's answers, a pull of many words) is
 * gathered into one snapshot. Counted from the first change, never pushed
 * back by later ones, so a widget is never more than this behind the app.
 */
export const SNAPSHOT_DEBOUNCE_MS = 800;

/** The tables a snapshot reads; a write anywhere else (the outbox, AI marks) changes nothing shown. */
const SHOWN_TABLES = /^idb:\/\/[^/]+\/(words|progress|notebooks|meta|dayStats|schedules)\//;

/** Whether a Dexie change notice touches a table the widgets draw from. */
export function touchesWidgets(parts: ObservabilitySet): boolean {
  return Object.keys(parts).some((key) => SHOWN_TABLES.test(key));
}

/** The snapshot without its build time, which changes on every build. */
function sameAs(a: WidgetSnapshot | undefined, b: WidgetSnapshot): boolean {
  if (a === undefined) return false;
  return JSON.stringify({ ...a, builtAt: '' }) === JSON.stringify({ ...b, builtAt: '' });
}

/** Errors here are logged, never shown: a widget that lags is not worth a message. */
function quietly(work: Promise<unknown>): void {
  work.catch((cause: unknown) => {
    console.error('widgets failed', cause);
  });
}

/**
 * Starts the loop for one account on a host that has widgets. Returns a stop
 * function; on a host without them it does nothing at all.
 */
export function startWidgets(account: string, host: HomeWidgets | undefined = platform.widgets): () => void {
  if (host === undefined) return () => undefined;
  let stopped = false;
  // A function, so a check made after an await reads the current value.
  const isStopped = (): boolean => stopped;
  let last: WidgetSnapshot | undefined;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let draining: Promise<void> | null = null;

  const push = async (): Promise<void> => {
    clearTimeout(timer);
    timer = undefined;
    if (isStopped()) return;
    const snapshot = await loadWidgetSnapshot(account, localTimeZone());
    if (isStopped() || sameAs(last, snapshot)) return;
    await host.setSnapshot(snapshot);
    last = snapshot;
  };
  const pushSoon = (): void => {
    if (timer !== undefined) return;
    timer = setTimeout(() => {
      quietly(push());
    }, SNAPSHOT_DEBOUNCE_MS);
  };

  // Words said to Siri (iPhone only): added, acknowledged, then filled by
  // AI where the learner already allowed it, without holding up the drain.
  const takeInSaidWords = async (): Promise<void> => {
    if (host.readAdds === undefined || host.ackAdds === undefined) return;
    const adds = await host.readAdds();
    if (adds.length === 0 || isStopped()) return;
    // The words, and the AI that fills them, came from Siri (lib/surface.ts).
    // A change the learner makes in the same moment reads as Siri's too; the
    // window is a few local writes long.
    const release = holdSurface('app.siri');
    let result: Awaited<ReturnType<typeof applySiriAdds>>;
    try {
      result = await applySiriAdds(adds, account, localTimeZone());
    } finally {
      release();
    }
    await host.ackAdds(result.done);
    if (result.wordIds.length === 0 || result.notebookId === undefined) return;
    void syncSoon();
    const unconfirmed = useAuth.getState().user?.emailVerified === false;
    const notebookId = result.notebookId;
    const wordIds = result.wordIds;
    quietly(withSurface('app.siri', () => fillSaidWords(notebookId, wordIds, unconfirmed)));
  };

  // One drain at a time: a resume that arrives mid-drain joins it.
  const drain = (): Promise<void> => {
    draining ??= (async () => {
      try {
        const answers = await host.readAnswers();
        if (answers.length > 0) {
          // Answers given on the word-card widget are the widget's (lib/surface.ts).
          const result = await withSurface('app.widget', () =>
            applyWidgetAnswers(answers, account, localTimeZone()),
          );
          await host.ackAnswers(result.done);
          // Graded answers are practice: pushed now, like a session's end.
          if (result.applied > 0) void flushPractice();
        }
        await takeInSaidWords();
        // A widget that answered and moved on may now be ahead of the last
        // snapshot sent; the next one always goes.
        last = undefined;
        await push();
      } finally {
        draining = null;
      }
    })();
    return draining;
  };

  quietly(drain());
  const offResume = platform.lifecycle.onResume(() => {
    quietly(drain());
  });
  const onHidden = (): void => {
    if (document.visibilityState === 'hidden') quietly(push());
  };
  document.addEventListener('visibilitychange', onHidden);
  // Every sync run that ends: a session's answers pushed, another device's pulled.
  const offSync = useSync.subscribe((now, before) => {
    if (before.phase === 'syncing' && now.phase !== 'syncing') pushSoon();
  });
  // Every local write the widgets would show, in this tab or another.
  const onChange = (parts: ObservabilitySet): void => {
    if (touchesWidgets(parts)) pushSoon();
  };
  Dexie.on('storagemutated', onChange);

  return () => {
    stopped = true;
    clearTimeout(timer);
    offResume();
    offSync();
    Dexie.on.storagemutated.unsubscribe(onChange);
    document.removeEventListener('visibilitychange', onHidden);
  };
}

/**
 * The screen a widget, shortcut or tile asked for. "Start" follows Today's
 * own button: an empty notebook opens the add sheet, a day whose limit is
 * reached walks the notebook, and every notebook in view comes along.
 */
export async function widgetPath(target: WidgetTarget): Promise<string> {
  switch (target) {
    case 'add':
      return '/notebook?add=1&type=1';
    case 'voice':
      return '/notebook?add=1&voice=1';
    case 'progress':
      return '/progress';
    case 'today':
      return '/';
    case 'start': {
      const data = await loadToday();
      if (data.counts.total === 0) return '/notebook?add=1';
      const query = new URLSearchParams();
      if (data.backlog && data.counts.due === 0) query.set('deck', 'notebook');
      if (data.practiceScope === 'all') query.set('scope', 'all');
      const search = query.toString();
      return search === '' ? '/session' : `/session?${search}`;
    }
  }
}
