/**
 * Answers given on the word-card widget, applied through the same review
 * path a session uses (`gradeCard`, so `review()` in @lexpad/core and the
 * outbox). The shell only queued the taps; every rule about what an answer
 * does to a word lives here and in core, and the server judges it as it
 * judges any offline answer, by its own time.
 */
import { dayIndex } from '@lexpad/core';
import { getWord, loadStreak } from '@/db/repo.js';
import { gradeCard } from '@/db/mutations.js';
import { db, type LexpadDb } from '@/db/schema.js';
import type { WidgetAnswer } from '@/lib/platform/index.js';

/** The deck an answer from the widget is logged under, so analysis can tell it apart. */
export const WIDGET_DECK = 'widget';

/** What became of a batch of answers. */
export interface AppliedAnswers {
  /** Answers graded now. */
  applied: number;
  /**
   * Answers that will never be graded: another account's, a word that is
   * gone, or one answered again since (here, or on another device).
   */
  dropped: number;
  /** Every answer that was dealt with, to acknowledge to the shell. */
  done: string[];
}

/**
 * Grades each answer, oldest first, as of the moment it was tapped.
 *
 * An answer is dropped rather than graded when it is not this account's
 * (the device changed hands; that account's words are gone from here), when
 * its word no longer exists, or when the word's progress changed at or after
 * the tap: somebody answered it since, and a grade on top of that would
 * count one look twice. That last rule also makes applying the same answer
 * twice a no-op, because a grade stamps the word with the tap's own time.
 *
 * A tap on an earlier day than the streak's last active day is graded as of
 * now instead: grading it on its own day would restart a streak that has
 * moved on since (`advanceStreak` treats any other day as a new run).
 */
export async function applyWidgetAnswers(
  answers: readonly WidgetAnswer[],
  account: string,
  timeZone: string,
  now: Date = new Date(),
  database: LexpadDb = db,
): Promise<AppliedAnswers> {
  const out: AppliedAnswers = { applied: 0, dropped: 0, done: [] };
  const ordered = [...answers].sort((a, b) => Date.parse(a.at) - Date.parse(b.at));
  for (const answer of ordered) {
    const tapped = new Date(Math.min(Date.parse(answer.at), now.getTime()));
    const word = answer.account === account ? await getWord(answer.wordId, database) : undefined;
    const changed = word?.progress?.updatedAt;
    if (word === undefined || (changed !== undefined && Date.parse(changed) >= tapped.getTime())) {
      out.dropped += 1;
      out.done.push(answer.id);
      continue;
    }
    const streak = await loadStreak(database);
    const day = dayIndex(tapped, timeZone);
    const when = streak.lastActiveDay !== undefined && day < streak.lastActiveDay ? now : tapped;
    await gradeCard(
      {
        wordId: answer.wordId,
        correct: answer.correct,
        cardType: 'classic',
        source: 'selftest',
        deck: WIDGET_DECK,
      },
      timeZone,
      when,
      database,
    );
    out.applied += 1;
    out.done.push(answer.id);
  }
  return out;
}
