/**
 * What the home-screen widgets (Android and iPhone) show, built from the local database
 * by the same rules as Today (features/today/data.ts): the counts, the
 * streak, the day's "all done", and the due words in the order a session
 * asks them. The shell only draws it; nothing here is worked out natively.
 */
import {
  activeToday,
  boxCounts,
  canPractise,
  countWords,
  dayIndex,
  directionOf,
  effectiveStreak,
  firstMeaning,
  type LanguageCode,
  type Word,
} from '@lexpad/core';
import { inView, listWords, loadHistory, loadStreak } from '@/db/repo.js';
import { db, getMeta, type LexpadDb } from '@/db/schema.js';
import { snapshotFor } from '@/features/billing/planSnapshot.js';
import { cappedDueWords } from '@/features/schedule/capped.js';
import type { WidgetCard, WidgetSnapshot } from '@/lib/platform/index.js';

/**
 * How many due words the snapshot carries. The word-card widget shows one at
 * a time and the app sends a fresh snapshot whenever it is opened, so a
 * day's worth is plenty; more would only make every push larger.
 */
export const WIDGET_CARDS = 20;

/**
 * The longest word or meaning a card carries, in characters. A widget shows
 * two or three lines at most; the rest of a long definition stays in the app.
 */
export const WIDGET_TEXT_MAX = 160;

/** Seven days, like Today's week strip. */
const WEEK = 7;

/**
 * How many days ahead the snapshot counts the words coming due. A widget drawn later than
 * that without the app having been opened says only that a new day has begun.
 */
export const SOON_DAYS = 7;

function clip(text: string): string {
  const flat = text.replace(/\s+/g, ' ').trim();
  return flat.length <= WIDGET_TEXT_MAX ? flat : `${flat.slice(0, WIDGET_TEXT_MAX - 1).trimEnd()}…`;
}

function cardOf(word: Word, notebook: { targetLang: LanguageCode; meaningLang: LanguageCode }): WidgetCard {
  return {
    id: word.id,
    word: clip(word.headword),
    meaning: clip(firstMeaning(word)),
    lang: notebook.targetLang,
    dir: directionOf(notebook.targetLang),
    meaningLang: notebook.meaningLang,
    meaningDir: directionOf(notebook.meaningLang),
  };
}

/** Reads everything the widgets show for this account, now. */
export async function loadWidgetSnapshot(
  account: string,
  timeZone: string,
  now: Date = new Date(),
  database: LexpadDb = db,
): Promise<WidgetSnapshot> {
  const today = dayIndex(now, timeZone);
  const { notebooks } = await inView(database);
  const [lists, week, streak, planKept] = await Promise.all([
    Promise.all(notebooks.map((one) => listWords(one.id, database))),
    loadHistory(WEEK, timeZone, now, database),
    loadStreak(database),
    getMeta('planSnapshot', database),
  ]);
  const plan = snapshotFor(planKept, account)?.plan;
  const words = lists.flat();
  const { capped, due, caps } = await cappedDueWords(notebooks, lists, today);
  const counts = { ...countWords(words, today), due: capped.due };
  // Today's rules: under a daily limit with more due than today has room
  // for, new words wait, so they are not promised here either.
  const fresh = capped.backlog ? 0 : counts.new;
  const doneToday = week.find((day) => day.day === today)?.reviewed ?? 0;
  const allDone =
    counts.total > 0 && counts.due + fresh === 0 && doneToday > 0 && !capped.backlog && capped.held === 0;

  const byId = new Map<string, Word>(words.map((word) => [word.id, word]));
  const cards: WidgetCard[] = [];
  notebooks.forEach((notebook, index) => {
    for (const id of due[index] ?? []) {
      if (cards.length >= WIDGET_CARDS) return;
      const word = byId.get(id);
      if (word === undefined) continue;
      cards.push(cardOf(word, notebook));
    }
  });

  let nextDue: number | undefined;
  const soonByDay = Array.from({ length: SOON_DAYS }, () => 0);
  const upcoming: { word: Word; notebook: (typeof notebooks)[number]; dueDay: number }[] = [];
  notebooks.forEach((notebook, index) => {
    for (const word of lists[index] ?? []) {
      const progress = word.progress;
      if (progress === undefined || progress.retired || progress.dueDay <= today) continue;
      if (nextDue === undefined || progress.dueDay < nextDue) nextDue = progress.dueDay;
      // Only words a session could ask (a word with no meaning waits outside practice).
      if (!canPractise(word)) continue;
      const ahead = progress.dueDay - today - 1;
      if (ahead < SOON_DAYS) {
        soonByDay[ahead] = (soonByDay[ahead] ?? 0) + 1;
        upcoming.push({ word, notebook, dueDay: progress.dueDay });
      }
    }
  });
  upcoming.sort((a, b) => a.dueDay - b.dueDay || (a.word.progress?.box ?? 0) - (b.word.progress?.box ?? 0));
  const soon = upcoming.slice(0, WIDGET_CARDS).map(({ word, notebook, dueDay }) => ({
    ...cardOf(word, notebook),
    dueDay,
  }));

  return {
    v: 1,
    account,
    day: today,
    builtAt: now.toISOString(),
    words: counts.total,
    due: counts.due,
    fresh,
    doneToday,
    allDone,
    nextDueIn: nextDue === undefined ? 0 : nextDue - today,
    streak: effectiveStreak(streak, today),
    streakTomorrow: effectiveStreak(streak, today + 1),
    streakToday: activeToday(streak, today),
    cards,
    soon,
    soonByDay,
    held: capped.held,
    reviewCap: caps.length > 0 && caps.every((cap) => cap > 0) ? caps.reduce((sum, cap) => sum + cap, 0) : 0,
    boxes: [...boxCounts(words)],
    mastered: counts.mastered,
    weekLearned: week.reduce((sum, day) => sum + day.newWords, 0),
    weekReviewed: week.reduce((sum, day) => sum + day.reviewed, 0),
    ...(plan === undefined ? {} : { plan }),
    ...(notebooks[0] === undefined ? {} : { lang: notebooks[0].targetLang }),
  };
}
